create table if not exists public.cloud_saves (code text primary key, wkey text not null, data jsonb not null, updated_at timestamptz not null default now()); alter table public.cloud_saves enable row level security; create or replace function public.cloud_put(p_code text, p_key text, p_data jsonb) returns boolean language plpgsql security definer set search_path = public as $$ begin if length(p_code) <> 8 or length(p_key) < 16 or octet_length(p_data::text) > 400000 then return false; end if; insert into cloud_saves(code, wkey, data) values (upper(p_code), p_key, p_data) on conflict (code) do update set data = excluded.data, updated_at = now() where cloud_saves.wkey = excluded.wkey; return found; end $$; create or replace function public.cloud_get(p_code text) returns jsonb language sql security definer set search_path = public as $$ select jsonb_build_object('d', data, 'k', wkey) from cloud_saves where code = upper(p_code) $$; grant execute on function public.cloud_put(text, text, jsonb), public.cloud_get(text) to anon; alter table public.players add column if not exists yard jsonb;
